n        content = f.read()\n    m = FRONTMATTER_RE.match(content)\n    if not m:\n        return {}, content\n    try:\n        data = yaml.safe_load(m.group(1))\n    except yaml.YAMLError:\n        return {}, content\n    if not isinstance(data, dict):\n        return {}, content\n    return data, content[m.end():]\n\n\ndef body_headings(body):\n    heads = []\n    for hm in re.finditer(r'^#{1,6}\\s+(.+?)\\s*$', body, re.M):\n        heads.append(re.sub(r'[^a-z ]', '', hm.group(1).lower()).strip())\n    return heads\n\n\ndef load_epics(artifacts_dir, strat_id):","is_error":false}]},"parent_tool_use_id":"chatcmpl-tool-ac630302fcccd357","agent_id":"ad22c06fe99316867","session_id":"177f2182-dcad-4f2f-b1fd-9c1f9eb2a18a","uuid":"e58125a4-a8ee-4e1c-a940-53ba3ca29d2f","timestamp":"2026-10-26T14:12:38.343Z","tool_result_meta":[{"id":"chatcmpl-tool-bc1e486e32aa5cc2","permission_decision":{"decision":"accept","source":"config","reason_type":"mode"}}],"subagent_type":"claude","task_description":"Decompose RHAISTRAT-9013"}
